from pathlib import Path
p=Path('admin.html')
s=p.read_text(encoding='utf-8')
marker='function torvoCategoryNames(){'
if marker not in s:
    old='<div class="field"><label>CATEGORY *</label><div class="masterRow"><input id="pCategory" class="upper" list="catX"><button class="mini" onclick="addMaster(&quot;category&quot;,&quot;pCategory&quot;)">+</button><button class="mini edit" onclick="editMaster(&quot;category&quot;,&quot;pCategory&quot;)">✎</button><button class="mini del" onclick="deleteMaster(&quot;category&quot;,&quot;pCategory&quot;)">🗑</button></div>'
    new='<div class="field torvoBrandField"><label>CATEGORY *</label><div class="masterRow torvoBrandMasterRow"><div class="torvoBrandInputWrap"><input id="pCategory" class="upper" list="catX"><button class="torvoBrandDropBtn" type="button" onclick="torvoToggleCategoryDropdown()" title="Select Category">▼</button></div><button class="mini torvoBrandAddBtn" type="button" onclick="torvoOpenCategoryManager()" title="Manage Category">+</button></div><div id="torvoCategoryDropdown" class="torvoBrandDropdown"></div>'
    if old not in s: raise SystemExit('Category target not found; no change made')
    s=s.replace(old,new,1)
    anchor='function previewPhoto(slot,file)'
    if anchor not in s: raise SystemExit('Safe JS anchor not found; no change made')
    js='''function torvoCategoryNames(){return Array.from(new Set([].concat(DB.categories||[],(DB.items||[]).map(function(x){return x.category})).filter(Boolean).map(U))).sort()}\nfunction torvoEnsureCategoryUI(){if(E("torvoCategoryManager"))return;var d=document.createElement("div");d.id="torvoCategoryManager";d.className="torvoBrandOverlay";d.innerHTML='<div class="torvoBrandCard"><div class="torvoBrandHead"><b>MANAGE CATEGORY</b><button type="button" onclick="torvoCloseCategoryManager()">×</button></div><div class="torvoBrandAdd"><input id="torvoCategoryNew" class="upper" placeholder="ADD CATEGORY NAME"><button type="button" onclick="torvoAddCategory()">+ ADD</button></div><div id="torvoCategoryMsg" class="torvoBrandMsg"></div><input id="torvoCategorySearch" class="torvoBrandSearch upper" placeholder="SEARCH CATEGORY" oninput="torvoRenderCategories()"><div id="torvoCategoryRows" class="torvoBrandRows"></div></div>';document.body.appendChild(d)}\nfunction torvoOpenCategoryManager(){torvoEnsureCategoryUI();window.torvoCategoryScrollY=window.scrollY||0;document.body.classList.add("torvoModalOpen");document.body.style.top="-"+window.torvoCategoryScrollY+"px";E("torvoCategoryManager").classList.add("show");E("torvoCategoryNew").value="";E("torvoCategorySearch").value="";E("torvoCategoryMsg").textContent="";torvoRenderCategories()}\nfunction torvoCloseCategoryManager(){var x=E("torvoCategoryManager");if(x)x.classList.remove("show");document.body.classList.remove("torvoModalOpen");document.body.style.top="";window.scrollTo(0,window.torvoCategoryScrollY||0)}\nfunction torvoCategoryMessage(t,bad){var x=E("torvoCategoryMsg");if(!x)return;x.textContent=t;x.className="torvoBrandMsg "+(bad?"bad":"ok")}\nfunction torvoAddCategory(){var v=U((E("torvoCategoryNew").value||"").trim());if(!v)return torvoCategoryMessage("ENTER CATEGORY NAME",true);if(torvoCategoryNames().some(function(x){return N(x)===N(v)}))return torvoCategoryMessage("CATEGORY ALREADY EXISTS",true);DB.categories=DB.categories||[];DB.categories.push(v);if(E("pCategory"))E("pCategory").value=v;logActivity("MASTER ADDED: "+v);saveDB();E("torvoCategoryNew").value="";torvoCategoryMessage("✓ SUCCESSFUL — "+v+" ADDED",false);torvoRenderCategories()}\nfunction torvoRenderCategories(){var q=N(E("torvoCategorySearch")?E("torvoCategorySearch").value:"");var a=torvoCategoryNames().filter(function(v){return !q||N(v).includes(q)});E("torvoCategoryRows").innerHTML=a.length?a.map(function(v){return '<div class="torvoBrandRow"><span>'+H(v)+'</span></div>'}).join(""):'<div class="torvoBrandEmpty">NO CATEGORY FOUND</div>'}\nfunction torvoToggleCategoryDropdown(){var box=E("torvoCategoryDropdown");if(!box)return;var open=box.classList.toggle("show");if(!open)return;box.innerHTML=torvoCategoryNames().map(function(v){return '<button type="button" data-category="'+H(v)+'" onclick="torvoSelectCategory(this)">'+H(v)+'</button>'}).join("")||'<div class="torvoBrandEmpty">NO CATEGORY ADDED</div>'}\nfunction torvoSelectCategory(btn){if(E("pCategory"))E("pCategory").value=btn.getAttribute("data-category")||"";var box=E("torvoCategoryDropdown");if(box)box.classList.remove("show")}\n'''
    s=s.replace(anchor,js+anchor,1)
p.write_text(s,encoding='utf-8')
